export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

// Minimum |hit| ratio kept at the paddle: a dead-centre contact must still
// give the ball a playable angle (|vx| >= PADDLE_HIT_MIN * 0.6 * ballSpeed).
const PADDLE_HIT_MIN = 0.15;

