// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. It is the overlap gate of the swept test below, and the
// exported primitive the tests pin down.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (swept, pure logic) ----------------------------------

// Tests the segment travelled by the ball during one step against a brick
// dilated by the ball radius (slab method: the ball becomes a point and the
// brick grows by BALL_R). Returns a hit descriptor, or null:
//   { mode: 'overlap' }           ball already overlaps the brick
//   { mode: 'approach', nx, ny }  segment enters the dilated box; the non-zero
//                                 component is the outward normal of the face
//                                 entered (-1 left/top, +1 right/bottom)
// The face of the real brick that is hit is the dilated slab entered last;
// on a corner both slabs are entered at the same time.
function sweptBrickHit(ball, brick, x0, y0) {
  const x1 = ball.x;
  const y1 = ball.y;
  const dx = x1 - x0;
  const dy = y1 - y0;
  const bx0 = brick.x - ball.r;
  const bx1 = brick.x + brick.w + ball.r;
  const by0 = brick.y - ball.r;
  const by1 = brick.y + brick.h + ball.r;

  let txIn = 0;
  let txOut = 1;
  let sx = 0;
  if (Math.abs(dx) < 1e-12) {
    if (x0 < bx0 || x0 > bx1) return null;
  } else {
    let t1 = (bx0 - x0) / dx;
    let t2 = (bx1 - x0) / dx;
    let s1 = -1;
    let s2 = 1;
    if (t1 > t2) {
      [t1, t2] = [t2, t1];
      [s1, s2] = [s2, s1];
    }
    txIn = t1;
    txOut = t2;
    sx = s1;
  }

  let tyIn = 0;
  let tyOut = 1;
  let sy = 0;
  if (Math.abs(dy) < 1e-12) {
    if (y0 < by0 || y0 > by1) return null;
  } else {
    let t1 = (by0 - y0) / dy;
    let t2 = (by1 - y0) / dy;
    let s1 = -1;
    let s2 = 1;
    if (t1 > t2) {
      [t1, t2] = [t2, t1];
      [s1, s2] = [s2, s1];
    }
    tyIn = t1;
    tyOut = t2;
    sy = s1;
  }

  const tmin = Math.max(0, txIn, tyIn);
  const tmax = Math.min(1, txOut, tyOut);
  if (tmin > tmax) return null;

  if (tmin === 0) {
    // The ball starts inside (or touching) the dilated box: resolve by minimal
    // penetration, but only when the ball really overlaps the brick.
    return collides(ball, brick) ? { mode: 'overlap' } : null;
  }

  // The segment enters the dilated box: the face is the slab entered last.
  if (Math.abs(txIn - tyIn) < 1e-9) return { mode: 'approach', nx: sx, ny: sy };
  if (txIn > tyIn) return { mode: 'approach', nx: sx, ny: 0 };
  return { mode: 'approach', nx: 0, ny: sy };
}

// Bounce off the left or right face and place the ball's edge exactly on it.
function flipOutX(ball, brick) {
  if (ball.x < brick.x + brick.w / 2) {
    ball.vx = -Math.abs(ball.vx);
    ball.x = brick.x - ball.r;
  } else {
    ball.vx = Math.abs(ball.vx);
    ball.x = brick.x + brick.w + ball.r;
  }
}

// Bounce off the top or bottom face and place the ball's edge exactly on it.
function flipOutY(ball, brick) {
  if (ball.y < brick.y + brick.h / 2) {
    ball.vy = -Math.abs(ball.vy);
    ball.y = brick.y - ball.r;
  } else {
    ball.vy = Math.abs(ball.vy);
    ball.y = brick.y + brick.h + ball.r;
  }
}

// Resolves a hit: flip the touched axis (both on a corner) and push the ball
// out of the rectangle along that axis, so the next frame does not re-invert.
function resolveHit(ball, brick, hit) {
  if (hit.mode === 'overlap') {
    const penX = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
    );
    const penY = Math.min(
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    if (Math.abs(penX - penY) < 1e-9) {
      flipOutX(ball, brick);
      flipOutY(ball, brick);
    } else if (penX < penY) {
      flipOutX(ball, brick);
    } else {
      flipOutY(ball, brick);
    }
    return;
  }
  if (hit.nx !== 0 && hit.ny !== 0) {
    flipOutX(ball, brick);
    flipOutY(ball, brick);
  } else if (hit.nx !== 0) {
    flipOutX(ball, brick);
  } else {
    flipOutY(ball, brick);
  }
}

// Brick collision for one step, from the position (x0, y0) the ball occupied
// before the integration. Every overlapping brick dies and scores; the ball
// bounces at most once per pass — a second brick overlapped on the same seam
// must not re-invert the velocity it just received.
function bounceBricks(state, x0, y0) {
  const { ball } = state;
  let bounced = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(ball, brick, x0, y0);
    if (!hit) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (bounced) continue;
    resolveHit(ball, brick, hit);
    bounced = true;
    x0 = ball.x;
    y0 = ball.y;
  }
}

