edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick collision is swept: the segment
// travelled by the ball is tested, so a fast ball cannot tunnel through.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const x0 = ball.x;
  const y0 = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

edits.oldText:
