function flipOutX(ball, brick, side) {
  ball.vx = side < 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
  ball.x = side < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
}

// Bounce off the top or bottom face and place the ball's edge exactly on it.
// `side` is the face to exit through: -1 = top, +1 = bottom.
function flipOutY(ball, brick, side) {
  ball.vy = side < 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
  ball.y = side < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
}

