    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks: swept collision, one rebound per pass (score and combo live here).
  bounceBricks(state, x0, y0);

  // Paddle — swept: the ball must CROSS the paddle band during the step, not
  // land inside it, so a fast ball cannot tunnel through the paddle.
  if (
    ball.vy > 0 &&
    y0 + ball.r <= paddle.y + paddle.h &&
    ball.y + ball.r >= paddle.y &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit, but a dead-centre
    // hit must not leave `vx = 0`: the ball would loop vertically forever.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const hitClamped = Math.max(-1, Math.min(1, hit));
    const hitMin =
      Math.abs(hitClamped) < PADDLE_HIT_MIN
        ? (hitClamped < 0 ? -1 : 1) * PADDLE_HIT_MIN
        : hitClamped;
    ball.vx = ballSpeed(state.level) * 0.6 * hitMin;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

